// ---------------------------------------------------------------- CLI (host-independent self-test)

const isMain = process.argv[1] && path.resolve(process.argv[1]) === path.resolve(fileURLToPath(import.meta.url))
if (isMain) {
  const [, , name, ...rest] = process.argv
  if (!name || name === '--help') {
    console.log('usage: node archivist.mjs <tool> \'<json-args>\'')
    console.log('   or: node archivist.mjs <tool> --key=value --flag ...   (Windows-friendly, no JSON quoting)')
    console.log('tools: ' + TOOLS.map((t) => t.name).join(', '))
    process.exit(0)
  }
  const tool = TOOLS.find((t) => t.name === name)
  if (!tool) { console.error('unknown tool: ' + name); process.exit(1) }
  let args = {}
  if (rest.length === 1 && rest[0].trim().startsWith('{')) {
    try { args = JSON.parse(rest[0]) } catch (e) { console.error('bad json args: ' + e.message); process.exit(1) }
  } else {
    for (const token of rest) {
      const m = /^--([^=]+)(?:=(.*))?$/.exec(token)
      if (!m) { console.error('bad flag (expected --key=value): ' + token); process.exit(1) }
      const key = m[1].replace(/-/g, '_')
      let val = m[2]
      if (val === undefined) val = true
      else if (val === 'true' || val === 'false') val = val === 'true'
      else if (/^-?\d+(\.\d+)?$/.test(val)) val = Number(val)
      args[key] = val
    }
  }
  try {
    const out = tool.run(args)
    console.log(out)
  } catch (e) {
    console.error('error: ' + e.message)
    process.exit(1)
  }
}

// ---------------------------------------------------------------------------

const asText = (content: string) => ({ content })

export default Plugin.define({
  id: "archivist",
  async setup(ctx) {
    await ctx.tool.transform((editor) => {
      editor.namespace({
        name: "archivist",
        description: "Local LLM Wiki: a self-maintaining markdown knowledge base (raw sources + generated pages + deterministic search/lint/index/backup). Read the workspace AGENTS.md for the ingest/query/lint workflows.",
      })
      for (const tool of TOOLS) {
        editor.add({
          name: tool.name.replace(/^archivist_/, ""),
          description: tool.description,
          input: tool.schema,
          options: { namespace: "archivist", codemode: true },
          execute: async (input: unknown) => {
            try {
              return asText(String(tool.run((input ?? {}) as Record<string, unknown>)))
            } catch (error) {
              throw new Error(error instanceof Error ? error.message : String(error))
            }
          },
        })
      }
    })
  },
})
